      role1 = 704000,
      role2 = 701102,
      role3 = 701202,
      roleanim = 1.2,
      ruchang = 9,
      sentence = "Under his menacing gaze, I obediently shut my mouth, but I couldn't resist casting a few glances at him from the corner of my eye.",
      next = {7}
    },
    [7] = {
      beijing = 1363,
      dialog = 3,
      music = "17_Tension02",
      renwu = "npc",
      ruchang = 0,
      sentence = "He seemed to be gravely hurt, blood dripping in a stream down his forearm onto the floor. But one hand seemed to be clutching something tightly.",
