    },
    [12] = {
      beijing = 1363,
      dialog = 3,
      music = "17_Tension02",
      renwu = "npc",
      ruchang = 0,
      sentence = "I had no doubt that my nimble companion would be able to get himself out of the situation, but I had much lower hopes of my own chances.",
      next = {13}
    },
    [13] = {
      beijing = 1363,
      dialog = 3,
      music = "17_Tension02",
      renwu = "npc",
      ruchang = 0,
      sentence = "Footsteps grew closer. A cluster of people appeared at the end of the corridor. With nowhere to run, my anxiety levels spiked.",
      sfx = "Character_Footstep_02",
      next = {14}
    },
    [14] = {
      beijing = 1363,
      dialog = 3,
      music = "17_Tension02",
      renwu = "npc",
      role1 = 705000,
      role2 = 702102,
      role3 = 302205,
      roleanim = 1.2,
      ruchang = -1,
      sentence = "But Helios just perked an eyebrow and smiled, as if he didn't notice his wound at all. Then, as cool as a cucumber, he looked at me to see what I would do.",
      next = {101, 102}
    },
    [15] = {
      beijing = 1363,
      dialog = 3,
      music = "17_Tension02",
      renwu = "npc",
      ruchang = 0,
      sentence = "Our pursuers soon had us surrounded. He raised his gaze up to their dead black gun muzzles, and suddenly those gloomy eyes flashed with golden light.",
